    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    q = (y + dy, x + dx)
                    if 0 <= q[0] < h and 0 <= q[1] < w and grid[q[0]][q[1]] == 5 and q not in seen:
                        seen.add(q)
                        stack.append(q)
            r0, r1 = min(y for y, x in comp), max(y for y, x in comp)
            c0, c1 = min(x for y, x in comp), max(x for y, x in comp)
            top = sorted(x for y, x in comp if y == r0)
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    if grid[y][x] == 0:
                        out[y][x] = 2
            # The short top-stroke position indicates the side of extension:
            # a stroke inset from the left extends left; inset from right extends right.
            direction = 0
            if len(top) == 2:
                if top == [c0 + 1, c1]:
                    direction = -1
                elif top == [c0, c1 - 1]:
                    direction = 1
                elif top[0] == c0 and top[1] == c0 + 1:
                    direction = 1
                elif top[0] == c1 - 1 and top[1] == c1:
                    direction = -1
            if r0 > 0:
                if direction == -1:
                    xs = range(0, c1)
                elif direction == 1:
                    xs = range(c0 + 1, w)
                else:
                    xs = ()
                for x in xs:
                    if grid[r0 - 1][x] == 0:
                        out[r0 - 1][x] = 2
    return out

